<?php require __DIR__.'/../_init.php'; adminHeader('Categorys'); ?><a class="button" href="create.php">Add category</a><table><tr><th>Name</th><th>Slug</th><th>Actions</th></tr><?php foreach($pdo->query('SELECT * FROM categories ORDER BY id DESC') as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['slug']) ?></td><td><a href="edit.php?id=<?= (int)$r['id'] ?>">Edit</a> <form class="inline" method="post" action="delete.php" onsubmit="return confirm('Delete this item?')"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="danger">Delete</button></form></td></tr><?php endforeach ?></table><?php adminFooter(); ?>